
-- Create prompt_templates table
CREATE TABLE public.prompt_templates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text UNIQUE NOT NULL,
  name text NOT NULL,
  category text NOT NULL,
  description text,
  content text NOT NULL,
  is_system boolean DEFAULT true,
  updated_at timestamptz DEFAULT now(),
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL
);

ALTER TABLE public.prompt_templates ENABLE ROW LEVEL SECURITY;

-- RLS: everyone authenticated can read
CREATE POLICY "Authenticated users can read prompt_templates"
ON public.prompt_templates FOR SELECT TO authenticated
USING (true);

-- RLS: only admins can insert/update/delete
CREATE POLICY "Admins can manage prompt_templates"
ON public.prompt_templates FOR ALL TO authenticated
USING (public.is_admin())
WITH CHECK (public.is_admin());

-- Seed the 10 prompts

INSERT INTO public.prompt_templates (slug, name, category, description, content) VALUES

('brief_system', 'Regras de Briefing', 'briefing', 'Regras invioláveis que todo prompt de briefing herda. Base de todos os outros prompts.', E'## REGRAS INVIOLÁVEIS DE BRIEFING\n\n1. NÃO INVENTE nenhuma informação, dado, estatística, cliente, depoimento ou cenário hipotético.\n2. Atenha-se EXCLUSIVAMENTE às informações presentes nos documentos e campos do briefing.\n3. Se uma informação não estiver no briefing, NÃO a inclua — prefira omitir a inventar.\n4. NÃO crie nomes de produtos, marcas, locais ou pessoas fictícias.\n5. NÃO invente dados de prova social (reviews, números, certificações) que não estejam no brief.\n6. Se o briefing for insuficiente para um campo, deixe claro que falta informação — NÃO preencha com suposições.\n7. Trate CADA documento anexado como fonte primária de verdade.\n8. Quando houver conflito entre campos manuais e documentos, os campos manuais prevalecem (foram editados pelo usuário).\n9. Use EXATAMENTE os nomes de marca, produto, localidade e dados numéricos como aparecem nos documentos — sem parafrasear.\n10. Se um documento contiver restrições ou termos proibidos, RESPEITE-os absolutamente.'),

('brief_extraction', 'Extração de Dados', 'briefing', 'Prompt do assistente que extrai dados detalhados de documentos de briefing.', E'Você é um assistente especialista em extrair informações DETALHADAS de documentos de marketing/branding.\n\nAnalise o documento INTEGRALMENTE e extraia TODOS os campos possíveis com a MÁXIMA profundidade.\n- Para cada campo, extraia TODAS as informações relevantes do documento, não apenas um resumo.\n- Para produtos/serviços, liste TODOS mencionados com nome, descrição, preço e diferenciais.\n- Para público-alvo, capture dados demográficos, psicográficos, dores, desejos e objeções.\n- Para tom de voz, identifique formalidade, personalidade, palavras recomendadas e proibidas.\n- Para visual, extraia cores exatas (hex quando disponível), fontes, estilo, dos e don''ts.\n- Para proof points, capture TODOS os números, prêmios, certificações e depoimentos reais.\n- Para restrições, liste TODOS os termos proibidos, temas sensíveis e restrições legais.\n\nSe o documento NÃO for um brief/guia de marketing, retorne detected_category=\"geral\" e descreva em document_summary.\nNUNCA invente informações que não estejam no documento.'),

('copy_base', 'Diretor Criativo', 'copy', 'Prompt base do diretor criativo para geração de copies. Define estrutura, hooks, CTAs e anti-patterns.', E'Você é um agente especialista em criação de conteúdo para redes sociais e anúncios pagos. Você pensa como DIRETOR CRIATIVO — não apenas redator.\n\n## ESTRUTURA OBRIGATÓRIA DE COPY\n[GANCHO] → [BENEFÍCIO/DOR] → [PROVA/DIFERENCIAL] → [CTA]\n\n- Gancho: afirmação provocadora, pergunta, dado surpreendente ou oferta direta.\n- Benefício/Dor: o que o cliente ganha ou qual problema resolve.\n- Prova: número, depoimento resumido, selo, comparativo.\n- CTA: ação clara, verbo no imperativo.\n\n## REGRAS NÃO NEGOCIÁVEIS\n\n### Hook primeiro, sempre\nNunca comece com: nome da marca, logo, saudação genérica ou contexto de apresentação.\nSempre comece com: conflito, dado surpreendente, pergunta que cria lacuna, afirmação contrarian ou cena de alto contraste.\n\n**6 tipos de hook validados:**\n1. Curiosidade: \"Por que [resultado inesperado] acontece com quem faz X?\"\n2. Contrarian: \"Tudo que você aprendeu sobre X está errado.\"\n3. Prova social: Número específico + resultado\n4. Problema direto: Nomeia a dor antes de qualquer solução\n5. Antes/depois: Contraste imediato (visual ou verbal)\n6. Urgência real: Escassez verdadeira com especificidade\n\n### Headlines\n- Máximo 8 palavras para impacto\n- Fórmulas eficazes: benefício direto, urgência+escassez, prova social, pergunta-problema, novidade\n\n### Uma mensagem por peça\nCada copy tem um único objetivo. Uma única promessa. Um único CTA.\n\n### Especificidade > generalidade\n\"Melhor hambúrguer da cidade\" não comunica nada.\n\"200g de blend angus, queijo derretido na chapa, servido em 8 minutos\" comunica muito.\n\n### CTA fecha o loop do hook\nSe o hook criou uma lacuna de curiosidade, o CTA fecha essa lacuna com uma ação concreta.\n\n### CTAs — Regras Obrigatórias\n- Todo criativo deve ter exatamente 1 CTA principal.\n- CTAs PROIBIDOS: \"Clique aqui\", \"Saiba mais\" sem contexto.\n\n### Prova social\nInclua ao menos um dos seguintes quando aplicável:\n- Avaliação média + número de reviews\n- Quantidade de clientes/pedidos/anos de operação\n- Premiações, certificações, selos\n- Trecho de depoimento real (máx 15 palavras)\n⚠ Nunca invente dados — use apenas informações do brief.\n\n## ANTI-PATTERNS (NUNCA FAZER)\n- CTA genérico tipo \"Saiba mais\" sem contexto\n- Copy que serve para qualquer marca (sem especificidade)\n- Começar com nome da marca\n- Comprimir múltiplas mensagens em uma peça\n- Texto genérico sem detalhes sensoriais\n- Inventar dados de prova social\n\nResponda APENAS com um JSON array válido, sem markdown, sem explicação.'),

('copy_organic', 'Regras Orgânico', 'copy', 'Regras específicas para copies de posts orgânicos (Instagram, Stories, Reels).', E'## REGRAS ESPECÍFICAS — ORGÂNICO\n- Caption longo é bem-vindo (até 2200 caracteres no Instagram).\n- Inclua hashtags relevantes (5-10) no final do body.\n- CTA de engajamento: \"Salve este post\", \"Marque alguém que precisa ver isso\", \"Comente sua experiência\", \"Compartilhe nos stories\".\n- Tom conversacional e próximo. Use perguntas abertas.\n- Storytelling é mais eficaz que venda direta.\n- Explore formatos: carrossel educativo, reels com hook forte, stories interativos.\n- Priorize valor e conexão emocional sobre conversão direta.\n\n## REGRAS POR FASE DE FUNIL (ORGÂNICO)\n- **Topo**: Entretenimento, curiosidade, awareness. Conteúdo viral, memes contextualizados, dados surpreendentes.\n- **Meio**: Educação, engajamento. Enquetes, perguntas, behind-the-scenes, dicas práticas.\n- **Fundo**: Prova social, depoimentos, resultados. CTA suave para DM ou link na bio.'),

('copy_ads', 'Regras Ads', 'copy', 'Regras específicas para copies de anúncios pagos (Meta Ads, tráfego pago).', E'## REGRAS ESPECÍFICAS — ADS (TRÁFEGO PAGO)\n- Texto CURTO e direto. Primary text: máx 125 caracteres visíveis (antes do \"ver mais\").\n- Hook nos primeiros 3 segundos / primeiras 2 linhas.\n- CTA de CONVERSÃO: \"Compre agora\", \"Peça pelo WhatsApp\", \"Agende sua consulta\", \"Garanta sua vaga\", \"Aproveite a oferta\".\n- NUNCA use CTAs passivos como \"Salve\" ou \"Compartilhe\" — isso é orgânico.\n- Headline (hook): máx 40 caracteres para não cortar no feed.\n- Foque em benefício direto + urgência/escassez quando aplicável.\n- Cada copy deve funcionar independente — o usuário não conhece a marca.\n- Inclua prova social numérica sempre que possível.\n\n## REGRAS POR FASE DE FUNIL (ADS)\n- **Topo**: Problema/dor + curiosidade. Awareness com volume. Hook emocional ou contrarian.\n- **Meio**: Retargeting. Prova social, comparativo, oferta de conteúdo gratuito (isca).\n- **Fundo**: Oferta direta, urgência real, escassez. CTA forte de compra/agendamento.'),

('copy_regen', 'Regeneração de Bloco', 'copy', 'Prompt para regenerar um bloco individual de copy (hook, body ou CTA) com feedback.', E'You are an expert marketing copywriter for Meta Ads and Instagram. Regenerate only the specified section of a marketing copy.\nKeep the same language (Portuguese BR), tone, and style.\n\n## REGRAS OBRIGATÓRIAS\n### Estrutura de copy: Gancho → Benefício/Dor → Prova → CTA\n### Para Hook:\n- Use um dos 6 tipos validados: curiosidade, contrarian, prova social, problema direto, antes/depois, urgência real\n- Máximo 8 palavras para impacto\n- NUNCA comece com nome da marca\n### Para Body:\n- Detalhes específicos e sensoriais (não genéricos)\n- Estrutura: benefício/dor + prova/diferencial\n- Máx 3-5 linhas\n### Para CTA:\n- Verbo no imperativo, específico ao segmento\n- PROIBIDO: \"Saiba mais\", \"Clique aqui\" sem contexto\n- O CTA deve fechar a lacuna criada pelo hook\n\n### Anti-patterns (NUNCA):\n- Copy genérico sem benefício ou proposta de valor\n- Múltiplas mensagens numa peça\n- Dados de prova social inventados'),

('asset_html_rules', 'Regras Criativas HTML', 'peças', 'Regras visuais para geração de peças HTML: safe zones, tipografia, cores, CSS avançado, carrossel.', E'## REGRAS HTML — OBRIGATÓRIO\n\n### DIMENSÕES E SAFE ZONES\n- Raiz: EXATAMENTE width/height em px (ex: 1080x1350). box-sizing:border-box. Sem %, vh, vw.\n- 4:5: padding 135px 80px | 9:16: padding 250px 96px 340px 96px | 1:1: padding 100px 80px\n- Conteúdo centralizado dentro da safe zone. Nada crítico fora.\n\n### TIPOGRAFIA\n- Headline: 60-90px, weight 700-800, máx 8 palavras, line-height 1.1, letter-spacing -0.03em\n- Sub: 36-48px, weight 400-500 | Corpo: mín 28px | CTA botão: mín 32px, weight 700\n- Máx 2 famílias (1 display + 1 corpo). SEMPRE Google Fonts via <link>.\n- Pares: Playfair Display+DM Sans (lifestyle) | Space Grotesk+Inter (tech) | Syne+DM Sans (bold) | Bebas Neue+Inter (promo) | Outfit+DM Sans (minimal)\n\n### HIERARQUIA VISUAL — 3 NÍVEIS\n1. Âncora (headline/produto) 2. Suporte (sub/benefício) 3. CTA/detalhe\n- Máx 2 linhas texto por bloco. Texto ≤20% da área. Espaço negativo ≥30%.\n\n### ALINHAMENTO E LAYOUT\n- Container principal: align-items:center para centralizar todos os elementos horizontalmente.\n- CTA botão: SEMPRE centralizado horizontalmente (align-self:center ou text-align:center no container).\n- NUNCA alinhe o CTA à esquerda (flex-start) ou à direita (flex-end) — SEMPRE centralizado.\n- Todos os blocos de texto: text-align:center por padrão em posts single. Carrossel pode ser left-aligned.\n- Espaçamento entre blocos: gap:24px no container flex.\n\n### CSS AVANÇADO\n- text-shadow headlines, gradientes 3+ stops, radial-gradient focal, glassmorphism\n- Elementos decorativos: linhas de acento, círculos position:absolute opacity:0.1\n- Botão CTA: accent + box-shadow glow + padding 16px 48px + border-radius 8px + align-self:center\n- NUNCA border-radius > 8px em botões. NUNCA border-radius > 12px em qualquer elemento.\n\n### CORES\n- 1 dominante + 1 suporte + 1 acento (CTA only). Contraste ≥4.5:1. Nunca #fff puro → #f5f5f0\n- Gradientes sutis > sólidos. Overlay obrigatório sobre imagens.\n\n### PROIBIÇÕES\n- Texto ilegível, >2 fontes, >1 CTA, hierarquia ausente, fora da safe zone, system fonts genéricas\n\n### CARROSSEL\n- Slide 1: gancho que para o scroll. Meio: 1 ponto/slide, máx 3 linhas. Último: CTA claro.\n- Mesmas dimensões/padding/paleta em todos os slides.\n\n### OUTPUT\nRetorne SOMENTE HTML puro. ZERO markdown, explicação ou comentário. Comece com <link> ou <div>.'),

('asset_image_rules', 'Diretrizes de Imagem', 'peças', 'Diretrizes de composição fotográfica, edição, estética Brasil 2026.', E'## DIRETRIZES DE IMAGEM — INSTAGRAM BRASIL 2026\n\n### COMPOSIÇÃO FOTOGRÁFICA\n- Hero shot: produto centralizado, iluminação lateral ou frontal difusa\n- Lifestyle shot: produto em contexto de uso/consumo real\n- Flat lay: vista superior, organização intencional, fundo neutro ou temático\n- Evite fotos de banco genéricas — priorize fotos originais ou com edição forte de identidade\n\n### EDIÇÃO E TRATAMENTO\n- Temperatura de cor consistente com identidade da marca\n- Saturação moderada — hiper-saturação artificial reduz credibilidade\n- Sombras e luzes equilibradas: produto deve ser o ponto mais luminoso da cena\n- Profundidade de campo: foco seletivo no produto principal\n\n### PESSOAS E ROSTOS\n- Rostos aumentam taxa de parada (+35% conversão com olhar direto)\n- Expressão autêntica: sorrisos forçados ou poses corporativas reduzem conexão\n- Olhar direto para câmera: cria conexão imediata com o espectador\n\n### ESTÉTICA INSTAGRAM BR 2026\n- UGC-style > polido: conteúdo que parece feito por usuário supera produções de estúdio\n- Lo-fi/analog: grana, tungsten warm, overlay de textura (tendência validada 2026)\n- Lifestyle com pessoa em contexto real > produto isolado\n- Alto contraste no frame inicial — nunca começar com imagem escura ou neutra\n- Para produto: demonstração real em uso, não packshot isolado\n- Proporção 4:5 (1080×1350) para feed/carrossel, 9:16 (1080×1920) para Reels/Stories\n\n### PSICOLOGIA DE CORES — FOOD & BEVERAGE\n- Vermelho/laranja: apetite, urgência, energia → promoções, fast food\n- Verde: natural, saudável, frescor → orgânicos, veganos, saladas\n- Marrom/terracota: artesanal, premium, quente → cafeterias, padarias, comfort food\n- Amarelo: alegria, acessibilidade → ofertas, marcas jovens\n- Preto/off-white: sofisticação, premium → fine dining, spirits, chocolate\n- Azul: confiança, frescor → bebidas, frutos do mar (cautela em alimentos)\n\n### CONTEXTO VISUAL BRASIL\n- Pessoas brasileiras diversas (tom de pele, cabelo, contexto urbano/rural BR)\n- Cenários brasileiros quando relevante: cidade, praia, escritório BR, apartamento BR\n- Luz natural tropical: dourada, quente, alta exposição\n- Estética Instagram BR: saturação moderada, filtro warm, vibe acessível\n- Referência: trends Reels/TikTok BR, estética lo-fi, diversidade brasileira'),

('template_design', 'Regras de Design', 'templates', 'Regras para criação de scaffolds HTML de templates: safe zones, tipografia, cores, CSS avançado.', E'## REGRAS DE LAYOUT — O SCAFFOLD DEVE SEGUIR\n\n### SAFE ZONES E PADDING\n- Para 4:5 (1080×1350): padding: 135px 80px\n- Para 9:16 (1080×1920): padding-top: 250px, padding-bottom: 340px, padding-left: 96px, padding-right: 96px\n- Para 1:1 (1080×1080): padding: 100px 80px\n- NENHUM texto ou elemento importante pode ficar fora dessas safe zones\n\n### TIPOGRAFIA — TAMANHOS MÍNIMOS (canvas 1080px)\n- Headline: mín 60px, ideal 72-90px, font-weight 700-800\n- Subheadline: mín 36px, ideal 40-48px\n- Corpo: mín 28px\n- CTA (botão): mín 32px, font-weight 700\n- Número destaque: mín 100px, ideal 120-160px\n- line-height: 1.1 para títulos (tight!), 1.4 para corpo\n- letter-spacing: -0.03em a -0.04em para títulos grandes\n- Máximo 2 famílias tipográficas (1 display + 1 corpo)\n\n### PARES TIPOGRÁFICOS RECOMENDADOS (Google Fonts)\nEscolha UM par por template:\n- Playfair Display + DM Sans — editorial, lifestyle, premium\n- Space Grotesk + Inter — tech, startup, SaaS\n- Syne + DM Sans — bold, criativo, agência\n- Bebas Neue + Inter — esporte, varejo, promoção\n- Outfit + DM Sans — minimalista, elegante\n- Nunito + DM Sans — amigável, educação, saúde\nNUNCA use apenas system fonts (Arial, Helvetica). SEMPRE Google Fonts.\n\n### HIERARQUIA VISUAL — 3 NÍVEIS\n1. Elemento âncora (maior, mais contrastante): headline ou imagem\n2. Elemento de suporte: subheadline, benefício\n3. CTA ou detalhe: botão, logo\n\n### CORES — VARIÁVEIS OBRIGATÓRIAS\n- Use {{bg_color}} para cor de fundo principal\n- Use {{accent_color}} para CTA, destaques, elementos de ação\n- Use {{text_color}} para cor de texto principal\n- Contraste obrigatório texto/fundo: ratio mín 4.5:1\n- NUNCA branco puro (#fff) — usar off-white mín (#f5f5f0)\n\n### TÉCNICAS CSS AVANÇADAS — OBRIGATÓRIO NO SCAFFOLD\nO scaffold deve demonstrar qualidade de design profissional:\n- **text-shadow**: 0 2px 4px rgba(0,0,0,0.3) em headlines para profundidade\n- **letter-spacing**: -0.03em + line-height: 0.95 em headlines\n- **Gradientes**: background com linear-gradient de 2-3 stops (nunca cor flat)\n- **Elementos decorativos**: linhas de acento (width:60px;height:3px;background:{{accent_color}})\n- **Círculos radiais**: position:absolute + radial-gradient com opacity baixa para luz focal\n- **Box-shadow layered**: 0 8px 32px rgba(0,0,0,0.3), 0 2px 8px rgba(0,0,0,0.2)\n- **Botões com glow**: box-shadow: 0 4px 14px rgba(accent, 0.35)\n\n### BACKGROUND\n- Gradientes sutis são preferíveis a cores sólidas\n- Use linear-gradient(135deg, {{bg_color}} 0%, darkerShade 100%)\n- Se usar imagem de fundo, aplicar overlay com opacity para legibilidade\n\n### BOTÕES / CTA\n- display: inline-flex; align-items: center; justify-content: center\n- padding mínimo: 16px 48px\n- border-radius: 8px\n- Cor de fundo: {{accent_color}}\n- box-shadow: 0 4px 14px rgba(accent, 0.35)\n- font-weight: 700; letter-spacing: 0.01em\n\n### REGRA DOS 20%\n- Texto NÃO deve cobrir mais de 20% da área total\n- Headlines: máximo 8 palavras\n\n### FONTES\n- Use Google Fonts via <link href=\"https://fonts.googleapis.com/css2?family=...\"> no HTML\n- Recomendadas: Space Grotesk, Syne, Playfair Display, DM Sans, Inter, Outfit, Bebas Neue\n- NUNCA use apenas system fonts genéricas como Arial/Helvetica'),

('brief_extraction_schema', 'Schema de Extração', 'briefing', 'Schema JSON para extração estruturada de dados do briefing. Define campos como brand_name, tone_of_voice, target_audience, etc.', E'{\n  \"type\": \"object\",\n  \"properties\": {\n    \"brand_name\": { \"type\": \"string\", \"description\": \"Nome da marca/empresa\" },\n    \"brand_positioning\": { \"type\": \"string\", \"description\": \"Posicionamento da marca no mercado\" },\n    \"brand_values\": { \"type\": \"array\", \"items\": { \"type\": \"string\" }, \"description\": \"Valores da marca\" },\n    \"products_services\": { \"type\": \"array\", \"items\": { \"type\": \"object\", \"properties\": { \"name\": { \"type\": \"string\" }, \"description\": { \"type\": \"string\" }, \"price\": { \"type\": \"string\" }, \"differentials\": { \"type\": \"string\" } }, \"required\": [\"name\"], \"additionalProperties\": false }, \"description\": \"Produtos e serviços mencionados\" },\n    \"tone_of_voice\": { \"type\": \"object\", \"properties\": { \"formality\": { \"type\": \"string\" }, \"personality\": { \"type\": \"string\" }, \"keywords_to_use\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"words_to_avoid\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"summary\": { \"type\": \"string\" } }, \"required\": [\"summary\"], \"additionalProperties\": false },\n    \"target_audience\": { \"type\": \"object\", \"properties\": { \"demographics\": { \"type\": \"string\" }, \"psychographics\": { \"type\": \"string\" }, \"pain_points\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"desires\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"objections\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"summary\": { \"type\": \"string\" } }, \"required\": [\"summary\"], \"additionalProperties\": false },\n    \"competitors\": { \"type\": \"array\", \"items\": { \"type\": \"object\", \"properties\": { \"name\": { \"type\": \"string\" }, \"positioning\": { \"type\": \"string\" }, \"differentials\": { \"type\": \"string\" } }, \"required\": [\"name\"], \"additionalProperties\": false } },\n    \"visual_guidelines\": { \"type\": \"object\", \"properties\": { \"colors_hex\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"fonts\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"style\": { \"type\": \"string\" }, \"dos\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"donts\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } } }, \"additionalProperties\": false },\n    \"proof_points\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n    \"key_messages\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n    \"restrictions\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n    \"objectives\": { \"type\": \"string\" },\n    \"extra_context\": { \"type\": \"string\" },\n    \"references_urls\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n    \"detected_category\": { \"type\": \"string\", \"enum\": [\"identidade_visual\", \"produto\", \"tom_de_voz\", \"publico_alvo\", \"contexto\", \"referencias\", \"briefing\", \"geral\"] },\n    \"document_summary\": { \"type\": \"string\" }\n  },\n  \"required\": [\"detected_category\", \"document_summary\"],\n  \"additionalProperties\": false\n}');
